input_schema:
Research scope and validated sources
{
  "scope": "object - Output from Stage 1",
  "sources": "object - Output from Stage 2"
}

output_schema:
Synthesized findings with confidence levels and cross-source patterns
{
  "findings": [
    {
      "id": "string - e.g., F-001",
      "question_ref": "string - Which sub-question this answers",
      "finding": "string - The synthesized finding",
      "confidence": "high | medium | low",
      "confidence_rationale": "string - Why this confidence level",
      "supporting_evidence": [
        {
          "source_id": "string",
          "claim": "string",
          "strength": "strong | moderate | weak"
        }
      ],
      "contradicting_evidence": [
        {
          "source_id": "string",
          "claim": "string",
          "resolution": "string - How contradiction was handled"
        }
      ],
      "caveats": ["string - Important limitations or conditions"]
    }
  ],
  "patterns": [
    {
      "pattern": "string - Cross-source pattern observed",
      "supporting_findings": ["string - Finding IDs"],
      "significance": "string - Why this matters"
    }
  ],
  "uncertainties": [
    {
      "area": "string - What remains unclear",
      "reason": "string - Why it's uncertain",
      "impact": "string - How this affects conclusions",
      "mitigation": "string - How to handle"
    }
  ],
  "answer_assessment": {
    "primary_question_answered": "fully | partially | minimally",
    "sub_questions_answered": [
      {
        "question_id": "string",
        "status": "answered | partially_answered | unanswered",
        "finding_refs": ["string"]
      }
    ]
  }
}
